import { test } from 'node:test';
import assert from 'node:assert';
import { slugify } from '../src/slug.js';

test('basic title', () => {
  assert.strictEqual(slugify('Hello World!'), 'hello-world');
});

test('multiple spaces', () => {
  assert.strictEqual(slugify('Hello   World'), 'hello-world');
});

test('special characters', () => {
  assert.strictEqual(slugify('Hello@#$World'), 'hello-world');
});

test('numbers and letters', () => {
  assert.strictEqual(slugify('Hello 123 World'), 'hello-123-world');
});

test('leading and trailing non-alphanumerics', () => {
  assert.strictEqual(slugify('---Hello World---'), 'hello-world');
});

test('empty string', () => {
  assert.strictEqual(slugify(''), '');
});

test('only non-alphanumerics', () => {
  assert.strictEqual(slugify('!!!###$$$'), '');
});

test('already lowercase', () => {
  assert.strictEqual(slugify('hello-world'), 'hello-world');
});

test('mixed case with underscores', () => {
  assert.strictEqual(slugify('Hello_World_Test'), 'hello-world-test');
});

